package com.flowdesk.alert.recovery;

import com.fasterxml.jackson.annotation.JsonAnySetter;import com.flowdesk.common.authz.PermissionCode;import com.flowdesk.common.web.ApiException;import com.flowdesk.common.web.ApiMeta;import com.flowdesk.common.web.PageMeta;import com.flowdesk.common.web.RequestCorrelation;import com.flowdesk.common.web.RequiresPermission;import com.flowdesk.common.web.SuccessEnvelope;import jakarta.validation.Valid;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.CacheControl;import org.springframework.http.HttpHeaders;import org.springframework.http.ResponseEntity;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.Set;import java.util.UUID;
@RestController@RequestMapping("/api/v1/alert-message-recoveries")@ConditionalOnProperty(prefix="flowdesk.alert.ticket-result.entry",name="enabled",havingValue="true")public class AlertRecoveryController{private static final Set<String>PARAMS=Set.of("direction","state","deadLettered","lastErrorCode","recoveryRequiredFrom","recoveryRequiredTo","pageSize","pageToken","sort");private final AlertRecoveryService service;AlertRecoveryController(AlertRecoveryService s){service=s;}
    @GetMapping@RequiresPermission(PermissionCode.RECOVERY_READ_TENANT)public SuccessEnvelope<java.util.List<AlertRecoveryView>>list(@RequestParam MultiValueMap<String,String>p){validate(p);String d=p.getFirst("deadLettered");Boolean dead=d==null?null:switch(d){case"true"->true;case"false"->false;default->throw ApiException.badRequest("INVALID_QUERY_PARAMETER","deadLettered 必须是 true 或 false。");};int size=size(p.getFirst("pageSize"));var page=service.list(p.getFirst("direction"),p.getFirst("state"),dead,p.getFirst("lastErrorCode"),instant(p.getFirst("recoveryRequiredFrom")),instant(p.getFirst("recoveryRequiredTo")),size,p.getFirst("pageToken"),p.getFirst("sort"));return new SuccessEnvelope<>(page.items(),new ApiMeta(RequestCorrelation.current(),new PageMeta(page.items().size(),page.next(),page.sort())));}
    @GetMapping("/{recoveryId}")@RequiresPermission(PermissionCode.RECOVERY_READ_TENANT)public ResponseEntity<SuccessEnvelope<AlertRecoveryView>>get(@PathVariable UUID recoveryId){var v=service.get(recoveryId);return ResponseEntity.ok().header(HttpHeaders.ETAG,AlertRecoverySupport.etag(v.lockVersion())).body(new SuccessEnvelope<>(v,new ApiMeta(RequestCorrelation.current())));}
    @PostMapping("/{recoveryId}/replays")@RequiresPermission(PermissionCode.RECOVERY_REPLAY_TENANT)public ResponseEntity<SuccessEnvelope<AlertRecoveryView>>replay(@PathVariable UUID recoveryId,@Valid@RequestBody ReplayCommand command,@RequestHeader(name="Idempotency-Key",required=false)String key,@RequestHeader(name="If-Match",required=false)String match,@RequestParam MultiValueMap<String,String>query){if(!query.isEmpty())throw ApiException.badRequest("INVALID_QUERY_PARAMETER","人工重放端点不接受 query 参数。");var r=service.replay(recoveryId,command.reason(),key,match);return ResponseEntity.accepted().cacheControl(CacheControl.noStore()).header(HttpHeaders.ETAG,AlertRecoverySupport.etag(r.recovery().lockVersion())).header("Idempotency-Replayed",Boolean.toString(r.replayed())).body(new SuccessEnvelope<>(r.recovery(),new ApiMeta(RequestCorrelation.current())));}public record ReplayCommand(String reason){@JsonAnySetter public void reject(String f,Object ignored){throw new IllegalArgumentException("Alert replay request contains unknown field: "+f);}}
    private static void validate(MultiValueMap<String,String>p){for(String k:p.keySet()){if(!PARAMS.contains(k))throw ApiException.badRequest("UNKNOWN_QUERY_PARAMETER","请求包含未声明 query 参数。");if(p.get(k)==null||p.get(k).size()!=1||p.getFirst(k)==null||p.getFirst(k).isBlank())throw ApiException.badRequest("INVALID_QUERY_PARAMETER",k+" 必须出现一次且非空。");}}private static int size(String v){if(v==null)return 20;try{int n=Integer.parseInt(v);if(n<1||n>100)throw new Exception();return n;}catch(Exception e){throw ApiException.badRequest("INVALID_QUERY_PARAMETER","pageSize 必须为 1..100。");}}private static Instant instant(String v){if(v==null)return null;try{return Instant.parse(v);}catch(Exception e){throw ApiException.badRequest("INVALID_QUERY_PARAMETER","时间 query 参数无效。");}}
}
